    /**
     * Handles loading a Campaign using a UUID
     * @param		UUID uuid 
     * @return		Campaign
     */    
    @GetMapping("/load")
    public Campaign load( @RequestParam(required=true) UUID uuid ) {    	
    	Campaign entity = null;

    	try {  
    		entity = service.getCampaign( new CampaignFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Campaign using Id " + uuid );
            return null;
        }

        return entity;
    }

